import torch


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = ctx["x__dtype"]
    if isinstance(dtype, str):
        dtype = getattr(torch, dtype)
    # Source uses torch.rand (uniform [0,1)) to keep log2 in its valid domain.
    x = torch.rand(shape, dtype=dtype, device=device)
    return {"x": x}


def run_correctness(x):
    x.copy_(torch.log2(x.float()).to(x.dtype))
    return x


def run(x):
    return torch.log2_(x)


def valid(ref_outputs, sol_outputs, inputs, ctx):
    ref = ref_outputs[0].detach().to("cpu").to(torch.float64)
    sol = sol_outputs[0].detach().to("cpu").to(torch.float64)
    finite = torch.isfinite(ref) & torch.isfinite(sol)
    close = torch.zeros_like(ref, dtype=torch.bool)
    close[finite] = torch.isclose(
        sol[finite], ref[finite], rtol=1.3e-6, atol=1e-4
    )
    same_nan = torch.isnan(ref) & torch.isnan(sol)
    same_posinf = torch.isposinf(ref) & torch.isposinf(sol)
    same_neginf = torch.isneginf(ref) & torch.isneginf(sol)
    passed = bool((close | same_nan | same_posinf | same_neginf).all().item())
    return {"passed": passed, "message": "", "metrics": {}}
